std::vector<utility::string_t> AdResponse::fromRejected_reasonsEnum(const std::vector<Rejected_reasonsEnum>& value) const
{
    std::vector<utility::string_t> ret;
    for (auto it = value.begin(); it != value.end(); it++) {
        ret.push_back(fromRejected_reasonsEnum(*it));
    }
    return ret;
}

std::vector<AdResponse::Rejected_reasonsEnum> AdResponse::toRejected_reasonsEnum(const std::vector<utility::string_t>& value) const
{
    std::vector<Rejected_reasonsEnum> ret;
    for (auto it = value.begin(); it != value.end(); it++) {
        ret.push_back(toRejected_reasonsEnum(*it));
    }
    return ret;
}
AdResponse::Review_statusEnum AdResponse::toReview_statusEnum(const utility::string_t& value) const
{
    
    if (value == utility::conversions::to_string_t("OTHER")) {
        return Review_statusEnum::OTHER;
    }
    
    if (value == utility::conversions::to_string_t("PENDING")) {
        return Review_statusEnum::PENDING;
    }
    
    if (value == utility::conversions::to_string_t("REJECTED")) {
        return Review_statusEnum::REJECTED;
    }
    
    if (value == utility::conversions::to_string_t("APPROVED")) {
        return Review_statusEnum::APPROVED;
    }
    
    throw std::invalid_argument("Invalid value for conversion to Review_statusEnum");
}


